style.css:
/* Retro Pac-Man dark blue theme */
body {
  position: relative;
  min-height: 100vh;
  margin: 0;
  background: none;
  overflow: hidden;
  font-family: 'Press Start 2P', monospace, sans-serif; /* optional arcade font */
}

/* Dark blue background */
body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -2;

  background: #0a0f40; /* deep arcade blue */
}

/* Moving dots (Pac-Man pellets) */
body::after {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 200%;
  height: 200%;
  z-index: -1;
  pointer-events: none;

  background-image: radial-gradient(circle, #ffe600 20%, transparent 21%);
  background-size: 40px 40px; /* grid of dots */
  animation: pelletMove 30s linear infinite;
}

/* Animate pellets (slow drift) */
@keyframes pelletMove {
  from { transform: translate(0, 0); }
  to   { transform: translate(-40px, -40px); }
}

/* === TEXT COLORS === */
/* Default (black text) → white */
body, body * {
  color: #ffffff;
}

/* Optional: make links neon cyan for arcade feel */
a {
  color: #00ffff !important;
}
